import{_ as e,o as t,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"A/B slots, install, and OTA updates","description":"","frontmatter":{},"headers":[],"relativePath":"manual/update-ota.md","filePath":"manual/update-ota.md"}'),n={name:"manual/update-ota.md"};function i(l,a,d,c,p,r){return t(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="a-b-slots-install-and-ota-updates" tabindex="-1">A/B slots, install, and OTA updates <a class="header-anchor" href="#a-b-slots-install-and-ota-updates" aria-label="Permalink to &quot;A/B slots, install, and OTA updates&quot;">​</a></h1><h2 id="the-a-b-scheme" tabindex="-1">The A/B scheme <a class="header-anchor" href="#the-a-b-scheme" aria-label="Permalink to &quot;The A/B scheme&quot;">​</a></h2><p><code>kernel/ota/ota_ab.c</code> maintains two slots (A and B) plus a boot flag:</p><ul><li>GRUB reads the flag and boots the active slot; the menu offers force-slot entries as the manual override.</li><li>An update installs onto the <em>inactive</em> slot while you keep running.</li><li>The next boot flips to the updated slot; <code>update rollback</code> flips back if you reject it.</li></ul><h2 id="installing-to-a-disk" tabindex="-1">Installing to a disk <a class="header-anchor" href="#installing-to-a-disk" aria-label="Permalink to &quot;Installing to a disk&quot;">​</a></h2><p>From a running ISO boot:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dskstat                (pick a target disk, e.g. ata0)</span></span>
<span class="line"><span>oc&gt; install ata0           (partition + copy the running kernel +</span></span>
<span class="line"><span>                            GRUB boot files + /etc volume)</span></span></code></pre></div><p><code>install</code> copies the multiboot2 module <code>self</code> - literally the kernel ELF that is running right now - onto the disk, so the installed system always matches its installer. <code>abdisk &lt;dev&gt;</code> does the same shaped as an A/B update disk (two slots + flags; destroys data).</p><p><code>abcfg</code> shows the exact grub.cfg files those commands write.</p><h2 id="checking-for-updates" tabindex="-1">Checking for updates <a class="header-anchor" href="#checking-for-updates" aria-label="Permalink to &quot;Checking for updates&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; checkupdate            (reads the update URL from /etc/opencube.conf</span></span>
<span class="line"><span>                            - http or https - and parses the manifest)</span></span>
<span class="line"><span>oc&gt; config get update_url  (the configuration key it uses)</span></span></code></pre></div><p>The manifest is the website&#39;s <code>update.json</code>: version, build, package URL, package SHA256, size.</p><h2 id="applying-an-update" tabindex="-1">Applying an update <a class="header-anchor" href="#applying-an-update" aria-label="Permalink to &quot;Applying an update&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; update download        (fetch the OTA package)</span></span>
<span class="line"><span>oc&gt; update verify          (SHA256 + signature check)</span></span>
<span class="line"><span>oc&gt; update install a       (install onto slot A/B - the inactive one)</span></span>
<span class="line"><span>oc&gt; reboot                 (boot the updated slot)</span></span></code></pre></div><p>The OTA package (<code>opencube-&lt;version&gt;-update.tar.gz</code>) carries the new kernel ELF plus a manifest. Verification is cryptographic: hash plus signature - a package that fails either is refused.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>If a slot misbehaves after a flip:</p><ol><li>Pick the other slot from the GRUB menu (force entry), or</li><li><code>oc&gt; update rollback</code> from inside a running system.</li></ol><p><code>ab_partition_test</code> exercises slot discovery, flags and slot switching on a scratch disk without touching your real boot disk.</p><h2 id="update-related-commands" tabindex="-1">Update-related commands <a class="header-anchor" href="#update-related-commands" aria-label="Permalink to &quot;Update-related commands&quot;">​</a></h2><p><code>checkupdate</code>, <code>checkupdate_test</code>, <code>update</code> (the chain above), <code>ab_partition_test</code>, <code>abcfg</code>, <code>abdisk</code>, <code>config</code> (update URL keys). The full list with one page each: <a href="./commands/">commands index</a> - &quot;OTA updates and A/B slots&quot; domain.</p><h2 id="internals" tabindex="-1">Internals <a class="header-anchor" href="#internals" aria-label="Permalink to &quot;Internals&quot;">​</a></h2><p>For how the flags are stored, how install stages the inactive slot, and the boot-flag handshake with GRUB, see <a href="./../internals/ota-ab.html">../internals/ota-ab.md</a>.</p>`,23)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
